#!/usr/bin/env node
/** Install a pre-push hook that refuses a push which would carry a secret. */
import { execFileSync } from "node:child_process";
import { chmodSync, existsSync, mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import process from "node:process";

const HOOK = `#!/bin/sh
# Generated by npm run hooks:install. Hooks are local; install them per clone.
exec npm run check:secrets -- --all-worktrees
`;

function hookPath() {
  const gitPath = execFileSync(
    "git", // NOSONAR:S4036 -- git is a fixed developer binary resolved from PATH; local tooling, not a privileged service.
    ["rev-parse", "--git-path", "hooks/pre-push"],
    { encoding: "utf8" },
  ).trim();
  return path.resolve(gitPath);
}

function main() {
  const force = process.argv.includes("--force");
  const unknown = process.argv.slice(2).find((arg) => arg !== "--force");
  if (unknown) {
    process.stderr.write(`hooks: unknown argument: ${unknown}\nUsage: node scripts/install-hooks.mjs [--force]\n`);
    return 2;
  }

  let file;
  try {
    file = hookPath();
  } catch (error) {
    process.stderr.write(`hooks: cannot resolve the git hooks path: ${error instanceof Error ? error.message : String(error)}\n`);
    return 1;
  }

  if (existsSync(file) && !force) {
    process.stderr.write(`hooks: ${file} already exists; pass --force to replace it\n`);
    return 1;
  }

  mkdirSync(path.dirname(file), { recursive: true });
  writeFileSync(file, HOOK, { mode: 0o755 });
  chmodSync(file, 0o755);
  process.stdout.write(`hooks: wrote ${file}\n`);
  process.stdout.write("hooks: hooks are local; run `npm run hooks:install` in every clone.\n");
  return 0;
}

process.exitCode = main();
